<script lang="ts">
	/**
	 * Supplied brand animation, used while the survey runs.
	 *
	 * Inlined rather than served as a static <img> for one reason: the cube
	 * faces are filled with the page background so the forms occlude each other
	 * properly. A fixed white fill reads correctly on the light theme and turns
	 * into solid white blocks on the dark one, and a transparent fill shows every
	 * hidden edge at once, which loses the 3D read entirely. Only CSS variables
	 * give both themes the right answer, and those do not cross into an <img>.
	 */
	let { size = 128 }: { size?: number } = $props();

	let svgEl = $state<SVGSVGElement | undefined>(undefined);

	// SMIL ignores prefers-reduced-motion, so honour it ourselves. This runs
	// during a 40-second wait, which is exactly when it matters.
	$effect(() => {
		if (!svgEl) return;
		if (window.matchMedia?.('(prefers-reduced-motion: reduce)').matches) {
			svgEl.pauseAnimations();
		}
	});
</script>

